const EventEmitter = require('events');
const { HttpRequestRedaction, GenericNodeRedaction } = require('./redaction-util');
const tenantConfigModel = require('../../../libs/custom-mongo-storage-plugin/tenants');
const apps = require('../../../libs/custom-mongo-storage-plugin/appConfig')
const red = require('../lib/red');
const logger = require('./pino-logger')

const MAX_DEPTH = process.env.REDACTION_LEVEL;
const getMaxTimeMs = () => parseInt(process.env.MAX_TIME_MS || 2000);

function removeCircularKeys(obj, maxDepth, currentDepth = 0) {
  if (currentDepth > maxDepth) {
    return obj;
  }
  const seen = new WeakSet();
  function removeCircular(current, depth) {
    if (typeof current !== "object" || current === null) {
      return current; // Return primitives as-is
    }
    if (seen.has(current)) {
      return undefined; // Circular reference detected
    }
    seen.add(current);
    const result = Array.isArray(current) ? [] : {};
    for (const key in current) {
      if (Object.prototype.hasOwnProperty.call(current, key)) {
        const value = removeCircular(current[key], depth + 1);
        if (value !== undefined) {
          result[key] = value;
        }
      }
    }
    return result;
  }
  return removeCircular(obj, currentDepth);
}

function removeKeys(obj, keysToRemove, maxDepth, currentDepth = 0) {
  if (currentDepth > maxDepth) {
    return obj;
  }
  if (typeof obj !== "object" || obj === null) {
    return obj; // Return non-objects as-is
  }
  const keysToRemoveSet = new Set(keysToRemove);
  for (const key in obj) {
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      if (keysToRemoveSet.has(key)) {
        delete obj[key];
      } else {
        obj[key] = removeKeys(obj[key], keysToRemove, maxDepth, currentDepth + 1);
      }
    }
  }
  return obj;
}
class LogEmitter extends EventEmitter {
  constructor() {
    super();
    this.redactionStrategies = {
      "http request": new HttpRequestRedaction(),
      "generic redaction": new GenericNodeRedaction()
    };
    this.on('runTimeLog', async (record) => {
      const red = require('../lib/red')
      if (record.nodeType === 'catch') {
        return;
      }
      if (process.env.RUNTIME_LOGS) {

        let tenantData, appData;
        let wait = [tenantConfigModel.findById(record.tenantConfigId), apps.findById(record.appId)]
        try {
          [tenantData, appData] = await Promise.all(wait)
          tenantData = tenantData.toObject(); //convert model to object
          appData = appData.toObject();
          let redactConfig = tenantData.redactConfig || {};
          let removableKeys = tenantData.runTimeLogs.removableKeys || [];
          if (process.env.RUNTIME_LOGS_REMOVABLE_KEYS) {
            removableKeys.push(...process.env.RUNTIME_LOGS_REMOVABLE_KEYS.split(','));
          }

          if (record.nodeOut.error) {
            nodeError = {};
            nodeError["message"] = record.nodeOut.error.message;
            nodeError["stack"] = record.nodeOut.error.stack;
            record.nodeError = nodeError
          }
          if (record.isErrorPresent) {
            record.workflowStatus = 'failed'
          }
          //remove circular dependencies
          record.nodeIn = removeCircularKeys(record.nodeIn, MAX_DEPTH);
          record.nodeOut = removeCircularKeys(record.nodeOut, MAX_DEPTH);
          //redaction
          let enableRedaction = redactConfig.enable !== undefined ? redactConfig.enable : process.env.REDACTION_ENABLE === 'true';
          if (enableRedaction) {
            redactConfig.valuePattern = redactConfig.valuePattern ? redactConfig.valuePattern.map(str => new RegExp(str)) : process.env.REDACTION_VALUEPATTERN.split(',').map(str => new RegExp(str));
            redactConfig.keyPattern = redactConfig.keyPattern ? redactConfig.keyPattern.map(str => new RegExp(str)) : process.env.REDACTION_KEYPATTERN.split(',').map(str => new RegExp(str));
            redactConfig.nonRedactableKeys = redactConfig.nonRedactableKeys || process.env.REDACTION_NON_REDACT.split(',');
            if (record.nodeType in this.redactionStrategies) {
              const strategy = this.redactionStrategies[record.nodeType];
              record = strategy.redact(record, redactConfig);
            } else {
              const genericStrategy = this.redactionStrategies["generic redaction"];
              record = genericStrategy.redact(record, redactConfig, MAX_DEPTH);
            }
          }
          // Remove keys from nodeIn and nodeOut
          record.nodeIn = removeKeys(record.nodeIn, removableKeys, MAX_DEPTH);
          record.nodeOut = removeKeys(record.nodeOut, removableKeys, MAX_DEPTH);
          record.appId = record.appId
          record.nodeName = record.name
          record.nodeOut.apiExecution = record.apiExecution
          red.saveRuntimeLog({
            id: record.id,
            tenantConfigId: record.tenantConfigId,
            nodeName: record.nodeName,
            nodeId: record.nodeId,
            nodeType: record.nodeType,
            startTime: record.startTime,
            endTime: record.endTime,
            nodeIn: record.nodeIn,
            nodeOut: record.nodeOut,
            ...(record.nodeError && { nodeError: record.nodeError })
          })

          if (record.isStartNode) {
            await red.updateRuntimeLogsSummary({ id: record.id, tenantConfigId: record.tenantConfigId }, { startTime: record.startTime, workflowName: record.name, appId: record.appId, appName: appData.name, appType: record.appType, workflowStatus: 'in-progress', appType: record.appType }, { upsert: true })
          }
          if (record.nodeError) {
            await red.updateRuntimeLogsSummary({ id: record.id, tenantConfigId: record.tenantConfigId }, { workflowStatus: record.workflowStatus }, { upsert: false })
          }
          if (record.isLastNode) {
            await red.updateRuntimeLogsSummary({ id: record.id, tenantConfigId: record.tenantConfigId }, { endTime: record.endTime, workflowStatus: record.workflowStatus ? record.workflowStatus : 'success' }, { upsert: false })
          }

        } catch (error) {
          logger.error(error, 'unable to add the run time log')
        }
      }
    })
  }


}

module.exports = LogEmitter;
